   * 2. Paste your logo's , ,  etc. elements here.
   * 3. Add  class="logo-path logo-animate"  to every element you want drawn.
   *    For the yellow glow duplicate, add  class="logo-path logo-glow"  instead.
   * 4. Add  pathLength="1"  to every // — this makes the
   *    animation work regardless of how long or short your actual paths are.
   *
   * Example:
   *   
   * ─────────────────────────────────────────────────────────────────────
   */

  .logo-path {
    fill: none;
    stroke: #c1549c;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* stroke-dasharray/offset of 1 works because pathLength="1" normalises
     every path to a virtual length of 1, no matter its real pixel length. */
  .logo-animate {
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    animation: draw 4s ease-in-out infinite;
  }

  @keyframes draw {
    0%   { stroke-dashoffset:  1; opacity: 0.2; }
    55%  { stroke-dashoffset:  0; opacity: 1;   }
    80%  { stroke-dashoffset:  0; opacity: 1;   }
    100% { stroke-dashoffset: -1; opacity: 0.2; }
  }

  .logo-glow {
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    animation: draw 4s ease-in-out infinite;
    stroke: #ffcb3e;
    stroke-width: 0.8;
    opacity: 0.5;
    filter: blur(2.5px);
  }
